<div class="wrap">
  <h1>Hétvégi kirándulás – költségek osztása</h1>
  <p class="lead">Add hozzá a résztvevőket és a kiadásokat, a végén megmutatjuk, ki kinek tartozik.</p>

  <section class="card" aria-labelledby="people-h">
    <h2 id="people-h">Résztvevők</h2>
    <div class="add-row">
      <label class="field name"><span>Új résztvevő neve</span>
        <input id="newPerson" type="text" placeholder="pl. Gábor" autocomplete="off">
      </label>
      <button class="btn" id="addPerson" type="button">Hozzáadás</button>
    </div>
    <div class="chips" id="chips"></div>
  </section>

  <section class="card" aria-labelledby="exp-h">
    <h2 id="exp-h">Kiadások</h2>
    <div class="row">
      <label class="field"><span>Miért fizettetek?</span>
        <input id="expDesc" type="text" placeholder="pl. Üzemanyag, szállás, étkezés" autocomplete="off">
      </label>
      <label class="field"><span>Összeg (Ft)</span>
        <input id="expAmount" type="number" inputmode="numeric" min="0" step="1" placeholder="0">
      </label>
    </div>
    <div class="row">
      <label class="field"><span>Fizette</span>
        <select id="expPayer"></select>
      </label>
      <label class="field"><span>Kikre oszlik?</span>
        <select id="expSplit"></select>
      </label>
    </div>
    <button class="btn" id="addExp" type="button" style="width:100%">Kiadás hozzáadása</button>
    <ul id="expList" style="margin-top:16px"></ul>
    <div class="total" id="totalRow" hidden>
      <span>Összes kiadás</span><b id="totalAmt"></b>
    </div>
  </section>

  <section class="card" aria-labelledby="res-h">
    <h2 id="res-h">Eredmény</h2>
    <div id="result"></div>
  </section>

  <section class="card">
    <h2>Beállítások</h2>
    <button class="btn btn-ghost btn-sm" id="resetAll" type="button">Összes törlése</button>
  </section>

  <p class="sr" aria-live="polite" id="live"></p>
</div>

<script>
(function () {
  var KEY = 'trip-split-v1';
  var DEFAULTS = { people: ['Levente', 'Anna', 'Peti'], expenses: [] };
  var state = { people: [], expenses: [] };

  function load() {
    if (window.alfy && window.alfy.storage) {
      return window.alfy.storage.get(KEY).then(function (v) {
        if (v && Array.isArray(v.people) && Array.isArray(v.expenses)) state = v;
      }).catch(function () {});
    }
    return Promise.resolve();
  }
  function save() {
    if (window.alfy && window.alfy.storage) {
      window.alfy.storage.set(KEY, state).catch(function () {});
    }
  }

  var el = function (id) { return document.getElementById(id); };
  var fmt = function (n) { return new Intl.NumberFormat('hu-HU').format(Math.round(n)) + ' Ft'; };
  function announce(msg) { el('live').textContent = msg; }
  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;' }[c];
    });
  }

  function renderChips() {
    var box = el('chips');
    if (!state.people.length) { box.innerHTML = '<span class="empty">Még nincs résztvevő. Add hozzá őket fent.</span>'; return; }
    box.innerHTML = state.people.map(function (p, i) {
      return '<span class="chip"><b>' + esc(p) + '</b><button class="chip-x" data-i="' + i + '" aria-label="' + esc(p) + ' eltávolítása" type="button">&times;</button></span>';
    }).join('');
  }

  function renderSelects() {
    var opts = state.people.map(function (p) { return '<option value="' + esc(p) + '">' + esc(p) + '</option>'; }).join('');
    var payer = el('expPayer'), split = el('expSplit');
    var pSel = payer.value, sSel = split.value;
    payer.innerHTML = opts;
    split.innerHTML = '<option value="all">Mindenki</option>' + opts;
    if (state.people.indexOf(pSel) !== -1) payer.value = pSel;
    if (sSel === 'all' || state.people.indexOf(sSel) !== -1) split.value = sSel;
  }

  function renderExpenses() {
    var list = el('expList');
    if (!state.expenses.length) {
      list.innerHTML = '<li class="empty">Még nincs kiadás. Add hozzá az első fizetést fent.</li>';
      el('totalRow').hidden = true;
      return;
    }
    list.innerHTML = state.expenses.map(function (e, i) {
      var who = e.split === 'all' ? 'Mindenki' : e.split;
      return '<li class="exp"><div class="exp-main"><div class="exp-title">' + esc(e.desc) +
        '</div><div class="exp-meta">' + esc(e.payer) + ' fizette · ' + esc(who) + ' között</div></div>' +
        '<div class="exp-amt">' + fmt(e.amount) + '</div>' +
        '<button class="del" data-i="' + i + '" aria-label="' + esc(e.desc) + ' törlése" type="button">&times;</button></li>';
    }).join('');
    var total = state.expenses.reduce(function (s, e) { return s + e.amount; }, 0);
    el('totalAmt').textContent = fmt(total);
    el('totalRow').hidden = false;
  }

  function computeSettlements() {
    var n = state.people.length;
    var bal = {};
    state.people.forEach(function (p) { bal[p] = 0; });
    var total = 0;
    state.expenses.forEach(function (e) {
      if (!(e.payer in bal)) return;
      var participants = e.split === 'all' ? state.people.slice() : [e.split].filter(function (p) { return p in bal; });
      if (!participants.length) return;
      var share = e.amount / participants.length;
      bal[e.payer] += e.amount;
      participants.forEach(function (p) { bal[p] -= share; });
      total += e.amount;
    });
    var creditors = [], debtors = [];
    state.people.forEach(function (p) {
      if (bal[p] > 0.5) creditors.push({ name: p, amt: bal[p] });
      else if (bal[p] < -0.5) debtors.push({ name: p, amt: -bal[p] });
    });
    creditors.sort(function (a, b) { return b.amt - a.amt; });
    debtors.sort(function (a, b) { return b.amt - a.amt; });
    var tx = [];
    var ci = 0, di = 0;
    while (ci < creditors.length && di < debtors.length) {
      var amt = Math.min(creditors[ci].amt, debtors[di].amt);
      tx.push({ from: debtors[di].name, to: creditors[ci].name, amt: amt });
      creditors[ci].amt -= amt;
      debtors[di].amt -= amt;
      if (creditors[ci].amt <= 0.5) ci++;
      if (debtors[di].amt <= 0.5) di++;
    }
    return { total: total, balances: bal, tx: tx };
  }

  function renderResult() {
    var box = el('result');
    if (state.people.length < 2) {
      box.innerHTML = '<p class="hint">Legalább 2 résztvevő kell az elszámoláshoz.</p>';
      return;
    }
    if (!state.expenses.length) {
      box.innerHTML = '<p class="hint">Adj hozzá kiadást, hogy megmutassuk, ki kinek tartozik.</p>';
      return;
    }
    var r = computeSettlements();
    var html = '<h3>Egyenleg</h3><div>';
    state.people.forEach(function (p) {
      var v = r.balances[p];
      var cls = v > 0.5 ? 'pos' : (v < -0.5 ? 'neg' : '');
      var txt = Math.abs(v) < 0.5 ? 'kiegyenlítve' : (v > 0 ? '+' + fmt(v) + ' (kap)' : fmt(v) + ' (tartozik)');
      html += '<div class="bal"><span class="bal-name">' + esc(p) + '</span><span class="bal-val ' + cls + '">' + txt + '</span></div>';
    });
    html += '</div>';
    html += '<h3 style="margin-top:22px">Kinek kinek fizessen</h3>';
    if (!r.tx.length) {
      html += '<p class="hint">Mindenki kiegyenlítve – senki nem tartozik senkinek. 🎉</p>';
    } else {
      html += '<div>';
      r.tx.forEach(function (t) {
        html += '<div class="settle"><span class="settle-from">' + esc(t.from) + '</span>' +
          '<span class="settle-arrow">→</span><span class="settle-to">' + esc(t.to) + '</span>' +
          '<span class="settle-amt">' + fmt(t.amt) + '</span></div>';
      });
      html += '</div>';
    }
    box.innerHTML = html;
  }

  function renderAll() { renderChips(); renderSelects(); renderExpenses(); renderResult(); }

  function addPerson() {
    var input = el('newPerson');
    var name = input.value.trim();
    if (!name) { announce('Írd be a résztvevő nevét.'); input.focus(); return; }
    if (state.people.some(function (p) { return p.toLowerCase() === name.toLowerCase(); })) {
      announce('Ez a résztvevő már szerepel.'); return;
    }
    state.people.push(name);
    input.value = '';
    save(); renderAll(); input.focus();
    announce(name + ' hozzáadva.');
  }

  function addExpense() {
    var desc = el('expDesc').value.trim();
    var amount = parseFloat(el('expAmount').value);
    var payer = el('expPayer').value;
    var split = el('expSplit').value;
    if (!desc) { announce('Add meg, miért fizettetek.'); el('expDesc').focus(); return; }
    if (!payer) { announce('Előbb adj hozzá résztvevőket.'); return; }
    if (!(amount > 0)) { announce('Adj meg egy pozitív összeget.'); el('expAmount').focus(); return; }
    state.expenses.push({ desc: desc, amount: amount, payer: payer, split: split });
    el('expDesc').value = ''; el('expAmount').value = '';
    save(); renderAll();
    announce(desc + ' hozzáadva.');
  }

  el('addPerson').addEventListener('click', addPerson);
  el('newPerson').addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); addPerson(); } });
  el('addExp').addEventListener('click', addExpense);
  ['expDesc', 'expAmount'].forEach(function (id) {
    el(id).addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); addExpense(); } });
  });

  el('chips').addEventListener('click', function (e) {
    var b = e.target.closest('.chip-x'); if (!b) return;
    var i = +b.getAttribute('data-i');
    var removed = state.people.splice(i, 1)[0];
    state.expenses = state.expenses.filter(function (ex) { return ex.payer !== removed && ex.split !== removed; });
    save(); renderAll();
    announce(removed + ' eltávolítva.');
  });

  el('expList').addEventListener('click', function (e) {
    var b = e.target.closest('.del'); if (!b) return;
    var i = +b.getAttribute('data-i');
    var removed = state.expenses.splice(i, 1)[0];
    save(); renderAll();
    announce(removed.desc + ' törölve.');
  });

  el('resetAll').addEventListener('click', function () {
    if (!window.confirm('Biztosan törölsz minden résztvevőt és kiadást?')) return;
    state = { people: [], expenses: [] };
    save(); renderAll();
    announce('Minden törölve.');
  });

  load().then(renderAll);
})();
</script>
</body>
</html>
